"""Read-only live SQL Server catalog export. No application records or credentials."""
import json,subprocess
from pathlib import Path
from datetime import datetime,timezone
q={
'columns':"""SELECT s.name AS [schema],t.name AS [table],c.column_id AS ordinal,c.name,ty.name AS [type],c.max_length,c.precision,c.scale,c.is_nullable,c.is_identity,dc.definition AS [default],CAST(CASE WHEN pk.column_id IS NULL THEN 0 ELSE 1 END AS bit) AS is_primary_key FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id LEFT JOIN sys.default_constraints dc ON dc.object_id=c.default_object_id LEFT JOIN (SELECT ic.object_id,ic.column_id FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id WHERE i.is_primary_key=1) pk ON pk.object_id=c.object_id AND pk.column_id=c.column_id WHERE t.is_ms_shipped=0 ORDER BY s.name,t.name,c.column_id FOR JSON PATH""",
'foreign_keys':"""SELECT fk.name,OBJECT_SCHEMA_NAME(fk.parent_object_id) AS source_schema,OBJECT_NAME(fk.parent_object_id) AS source_table,pc.name AS source_column,OBJECT_SCHEMA_NAME(fk.referenced_object_id) AS target_schema,OBJECT_NAME(fk.referenced_object_id) AS target_table,rc.name AS target_column,fkc.constraint_column_id AS ordinal,fk.delete_referential_action_desc AS on_delete,fk.update_referential_action_desc AS on_update,fk.is_disabled,fk.is_not_trusted FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id=fk.object_id JOIN sys.columns pc ON pc.object_id=fk.parent_object_id AND pc.column_id=fkc.parent_column_id JOIN sys.columns rc ON rc.object_id=fk.referenced_object_id AND rc.column_id=fkc.referenced_column_id ORDER BY fk.name,fkc.constraint_column_id FOR JSON PATH""",
'unique_keys':"""SELECT OBJECT_SCHEMA_NAME(i.object_id) AS [schema],OBJECT_NAME(i.object_id) AS [table],i.name,c.name AS [column],ic.key_ordinal,i.is_primary_key,i.is_unique_constraint,i.has_filter,i.filter_definition FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id JOIN sys.tables t ON t.object_id=i.object_id WHERE i.is_unique=1 AND ic.key_ordinal>0 ORDER BY t.name,i.name,ic.key_ordinal FOR JSON PATH"""}
result={'database':'agora_db','captured_at':datetime.now(timezone.utc).isoformat(),'source':'Live SQL Server system catalog; no application rows exported'}
cmd='export SQLCMDPASSWORD="$MSSQL_SA_PASSWORD"; exec /opt/mssql-tools18/bin/sqlcmd -S tcp:127.0.0.1,1433 -U sa -C -d agora_db -b -y 0 -w 65535'
for key,query in q.items():
 output=subprocess.check_output(['docker','exec','-i','agora-mssql','bash','-lc',cmd],input=('SET NOCOUNT ON;\n'+query+';').encode()).decode()
 result[key]=json.loads(''.join(output.splitlines()).strip())
path=Path(__file__).resolve().parents[1]/'docs/database-erd/schema.json';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'tables':sorted(set(c['table'] for c in result['columns'])),'columns':len(result['columns']),'foreign_keys':len(result['foreign_keys'])},ensure_ascii=False))
